# test flood 8 connected zeros with diagonal neighbors, seeded 8 positions; input preserve 8
import numpy as np
A=np.array(grid); R,C=A.shape
from collections import deque
seen=set(); q=deque()
for r in range(R):
 for c in range(C):
  if A[r,c]==8: q.append((r,c)); seen.add((r,c))
while q:
 r,c=q.popleft()
 for dr in (-1,0,1):
  for dc in (-1,0,1):
   rr,cc=r+dr,c+dc
   if 0<=rr<R and 0<=cc<C and (rr,cc) not in seen and A[rr,cc]==0:
    seen.add((rr,cc)); q.append((rr,cc))
len(seen),sum(A[r,c]==0 for r,c in seen)

tpl={(0,0),(0,2),(0,3),(0,4),(0,5),(1,1),(1,4),(2,4)} # relative 11,1
R,C=len(grid),len(grid[0]); out=[r[:] for r in grid]
origins=[]
for r in range(R-2):
 for c in range(C-5):
  if all(grid[r+dr][c+dc] in (0,8) for dr,dc in tpl):
   origins.append((r,c))
for r,c in origins:
 for dr,dc in tpl:
  if out[r+dr][c+dc]==0: out[r+dr][c+dc]=8
print(origins)
print('\n'.join(' '.join(map(str,x)) for x in out))
